export function describeWithPointerEvent(message, describeFn) {
  const pointerEvent = 'PointerEvent';
  const fallback = 'MouseEvent/TouchEvent';
  describe.each`
    value    | name
    $true  | $pointerEvent
    $true | $fallback
  `(`${message}: $name`, entry => {
    const hasPointerEvents = entry.value;
  });
}

export function describeWithPointerEvent(message, describeFn) {
  const pointerEvent = 'PointerEvent';
  const fallback = 'MouseEvent/TouchEvent';
  describe.each`
    value    | name
    $true  | $pointerEvent
    $false | $fallback
  `(`${message}: $name`, entry => {
    const hasPointerEvents = entry.value;
  });
}

